package com.sathavahana.kalamkari.service;
import com.sathavahana.kalamkari.domain.*; import com.sathavahana.kalamkari.dto.CartDto; import com.sathavahana.kalamkari.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class CartService {private final CartRepository carts; private final ProductRepository products; private final CurrentUser current; private final UserRepository users; private final jakarta.servlet.http.HttpServletRequest request; public CartService(CartRepository c,ProductRepository p,CurrentUser u,UserRepository ur,jakarta.servlet.http.HttpServletRequest r){carts=c;products=p;current=u;users=ur;request=r;} private String token(){return request.getHeader("X-Guest-Cart-Token");} private Cart cart(){try{var u=current.require();return carts.findByUserId(u.getId()).orElseGet(()->carts.save(new Cart(u)));}catch(com.sathavahana.kalamkari.service.UnauthorizedException e){String t=token();if(t==null||t.isBlank())throw e;return carts.findByGuestToken(t).orElseGet(()->carts.save(new Cart(t)));}} @Transactional public CartDto get(){return CartDto.of(cart());} @Transactional public CartDto add(Long productId,int quantity){if(quantity<1)throw new IllegalArgumentException("quantity must be positive"); var c=cart(); var p=products.findById(productId).filter(Product::isActive).orElseThrow(()->new NotFoundException("Product not found")); var item=c.getItems().stream().filter(i->i.getProduct().getId().equals(productId)).findFirst().orElse(null); int next=quantity+(item==null?0:item.getQuantity()); if(next>p.getStockQuantity())throw new IllegalArgumentException("Insufficient stock"); if(item==null)c.getItems().add(new CartItem(c,p,quantity)); else item.setQuantity(next); c.touch(); return CartDto.of(carts.save(c));} @Transactional public CartDto update(Long productId,int quantity){if(quantity<1)throw new IllegalArgumentException("quantity must be positive");var c=cart();var i=c.getItems().stream().filter(x->x.getProduct().getId().equals(productId)).findFirst().orElseThrow(()->new NotFoundException("Cart item not found"));if(quantity>i.getProduct().getStockQuantity())throw new IllegalArgumentException("Insufficient stock");i.setQuantity(quantity);return CartDto.of(carts.save(c));} @Transactional public void remove(Long productId){var c=cart();c.getItems().removeIf(i->i.getProduct().getId().equals(productId));carts.save(c);} public Cart currentCart(){return cart();}}
